// Lists app/components/lib/workflows modules that no other file imports by name.
import fs from "node:fs";
import path from "node:path";

const files = [];
const walk = dir => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name).replaceAll("\\", "/");
    if (["node_modules", ".next", ".claude", ".git", ".qa"].includes(entry.name)) continue;
    if (entry.isDirectory()) walk(p);
    else if (/\.(ts|tsx|mjs)$/.test(entry.name)) files.push(p);
  }
};
walk(".");
const sources = new Map(files.map(f => [f, fs.readFileSync(f, "utf8")]));
const entry = /(^|\/)(page|layout|route|loading|error|not-found|template|default)\.tsx?$|\.test\.|\.spec\.|\.d\.ts$/;
for (const file of files) {
  if (!/^(app|components|lib|workflows)\//.test(file) || entry.test(file)) continue;
  const name = path.basename(file).replace(/\.(tsx?|mjs)$/, "");
  const pattern = new RegExp(`["'/]${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}["']`);
  const users = [...sources].filter(([other, text]) => other !== file && pattern.test(text)).map(([other]) => other);
  if (!users.length) console.log("UNUSED", file);
  else if (users.every(u => /\.test\./.test(u))) console.log("TEST-ONLY", file);
}

